// Program Transformer structure. MPTransformer(P, *args, [frmA, frmB]): // OBJ SELECTOR: Select objects in P via queries using any criteria // specified in the args. ... // OBJ TRANSFORMER: Apply an object operator to selected objects. ...
```

```
// Returns a list of object data which match some criteria. function objSelector(P, queryFn, queryType, criteria, [frmA, frmB]): selObjs = {} selObjsInfo = {} for each obj in selObjs: x = queryFn(obj, args.queryType, [frmA, frmB]) if x matches criteria: selObjs.insert(obj) selObjsInfo.insert(x) return selObjs, selObjsInfo
```

```
// Linear time scale by factor of k in frame range [frmA, frmB]. function linearRetimeObjTransformer(selObjs, k, [frmA, frmB]): for each obj in selObjs: sourceDur = frmB - frmA + 1 targetDur = k * sourceDur // Retime from source range [frmA, frmB] to target frame range // [frmA, frm + targetDur]. retime(obj, [frmA, frmB], [frmA, frmA + targetDur], f(t)=t)
```

```
// Retime to music beats (assume video has more segments than beats). function retimeToBeatsObjTransformer(selObjs, music, eventType, [frmA, frmB]): // Get music beat points using libROSA in units of frames. beatPts = getMusicBeatPts(music) for each obj in selObjs: // Form video segments for each beat segment between beat points based on // eventType. If eventType is null default to beatPts as segment points. if eventType == null: segPts = beatPts else: segPts = eventQuery(obj, eventType, [frmA, frmB]) for index i in segPts: // beatPts is in units of frames and includes a beat point at 0. retime(obj, [segPts[i], segPts[i + 1]], [beatPts[i], beatPts[i + 1]], f(t)=t^4)
```

```
// Add anticipation/follow through via Cartoon Animation Filter. function anticipateFollowThruObjTransformer(selObjs, [frmA, frmB], A, sigma): for each obj in selObjs: // Define the cartoon animation filter based on Wang et al. function cartoonAnimationFilter(t, obj, [frmA, frmB], A, sigma): // Copy and pad segment of xForms to be set up for convolution later. tmpXForms = copy(obj.xForms[frmA, frmB]) pad(tmpXForms, 0.5 * sigma) // -LoG is the inverse of the Laplacian of Gaussian function. newXForms = A * convolve(tmpXForms, -LoG(sigma)) return newXForms[t] adjGlobalMotion(obj, cartoonAnimationFilter, [frmA, frmB]
```
